17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.stereotype.Component;
21	import org.springframework.util.StringUtils;
22	import org.springframework.validation.Errors;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Enforces that every mandatory owner field is present and non-blank.
27	 * <p>
28	 * A field is rejected when it is missing (null), empty or whitespace-only. Registered on the
29	 * owner request binder so it runs during the standard {@code @Valid} pass, letting its rejections
30	 * surface through the same {@code BindingResult} as the Bean Validation constraints.
31	 */
32	@Component
33	public class OwnerFieldsValidator implements Validator {
34	
35	    @Override
36	    public boolean supports(Class<?> clazz) {
37	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
38	    }
39	
40	    @Override
41	    public void validate(Object target, Errors errors) {
42	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
43	        rejectIfBlank(errors, "firstName", owner.getFirstName());
44	        rejectIfBlank(errors, "lastName", owner.getLastName());
45	        rejectIfBlank(errors, "address", owner.getAddress());
46	        rejectIfBlank(errors, "city", owner.getCity());
47	        rejectIfBlank(errors, "telephone", owner.getTelephone());
48	    }
49	
50	    private void rejectIfBlank(Errors errors, String field, String value) {
51	        if (!StringUtils.hasText(value)) {
52	            errors.rejectValue(field, "required", "must not be blank");
53	        }
54	    }
55	}
