17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Guards owner creation against duplicate households: two owners are considered to share a
24	 * household when their last name and address match once compared case-insensitively and with
25	 * runs of whitespace collapsed to a single space.
26	 */
27	@Component
28	public class HouseholdDuplicateValidator {
29	
30	    private final Households households;
31	
32	    public HouseholdDuplicateValidator(Households households) {
33	        this.households = households;
34	    }
35	
36	    /**
37	     * Reject {@code candidate} when an existing owner already occupies the same household.
38	     *
39	     * @param candidate the owner about to be created
40	     * @throws DuplicateHouseholdException if another owner shares the candidate's last name and
41	     * address
42	     */
43	    public void validate(Owner candidate) {
44	        if (!households.findMembers(candidate).isEmpty()) {
45	            throw new DuplicateHouseholdException(candidate.getLastName(), candidate.getAddress());
46	        }
47	    }
48	}
