17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.List;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.service.ClinicService;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Joins an owner that opts into a shared household into the household of any existing owner at
27	 * the same address, giving every member the same stable {@code householdId}.
28	 */
29	@Component
30	public class HouseholdAssigner {
31	
32	    private final Households households;
33	
34	    private final ClinicService clinicService;
35	
36	    public HouseholdAssigner(Households households, ClinicService clinicService) {
37	        this.households = households;
38	        this.clinicService = clinicService;
39	    }
40	
41	    /**
42	     * Assign {@code candidate} the household identifier it shares with any existing same-household
43	     * owners, back-filling that identifier onto members that do not yet carry it. A no-op when no
44	     * existing owner shares the candidate's household.
45	     *
46	     * @param candidate the owner about to be created; its {@code householdId} is set in place
47	     */
48	    public void assignSharedHousehold(Owner candidate) {
49	        List<Owner> members = households.findMembers(candidate);
50	        if (members.isEmpty()) {
51	            return;
52	        }
53	        String householdId = households.stableId(candidate);
54	        candidate.setHouseholdId(householdId);
55	        for (Owner member : members) {
56	            if (!householdId.equals(member.getHouseholdId())) {
57	                member.setHouseholdId(householdId);
58	                clinicService.saveOwner(member);
59	            }
60	        }
61	    }
62	}
