31	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateValidator;
32	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
33	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.WebDataBinder;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.InitBinder;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    private final OwnerFieldsValidator ownerFieldsValidator;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final EmailNormalizer emailNormalizer;
77	
78	    private final HouseholdDuplicateValidator householdDuplicateValidator;
79	
80	    private final HouseholdAssigner householdAssigner;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 OwnerFieldsValidator ownerFieldsValidator,
87	                                 TelephoneNormalizer telephoneNormalizer,
88	                                 EmailNormalizer emailNormalizer,
89	                                 HouseholdDuplicateValidator householdDuplicateValidator,
90	                                 HouseholdAssigner householdAssigner) {
91	        this.clinicService = clinicService;
92	        this.ownerMapper = ownerMapper;
93	        this.petMapper = petMapper;
94	        this.visitMapper = visitMapper;
95	        this.ownerFieldsValidator = ownerFieldsValidator;
96	        this.telephoneNormalizer = telephoneNormalizer;
97	        this.emailNormalizer = emailNormalizer;
98	        this.householdDuplicateValidator = householdDuplicateValidator;
99	        this.householdAssigner = householdAssigner;
100	    }
101	
102	    /**
103	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
104	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
105	     */
106	    @InitBinder("ownerFieldsDto")
107	    void initOwnerFieldsBinder(WebDataBinder binder) {
108	        binder.addValidators(ownerFieldsValidator);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
142	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
143	            throw new DuplicateTelephoneException(telephone);
144	        }
145	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
146	            householdAssigner.assignSharedHousehold(owner);
147	        } else {
148	            householdDuplicateValidator.validate(owner);
149	        }
150	        owner.setTelephone(telephone);
151	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
152	        this.clinicService.saveOwner(owner);
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
