20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
33	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
35	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
36	import org.springframework.security.access.AccessDeniedException;
37	import org.springframework.validation.BindingResult;
38	import org.springframework.validation.FieldError;
